/* ============================ Đi dạo: vật cản thu từ cảnh đã dựng ============================
   Gọi MỘT lần, lần đầu vào chế độ (sau khi mọi bước dọn nhà đã chạy): chỉ đọc cảnh, không đụng chuỗi rand() hay thứ tự dựng (spec §6).
   - Nhà đang hiện (collectBuildings: level gần của THREE.LOD, bỏ instance scale 0) có chân đế chạm khung CONFIG.stroll.bounds: chữ nhật thẳng trục (nhà không xoay, city.ts).
   - Chân đế địa danh và pano ven sông (riverfront footprints), trừ chân đế có tâm trong vùng `love`: Cầu Tình Yêu đi được, lan can / tượng đã dựng riêng ở mapData.ts.
   Vật cản hỏng (số không hữu hạn, rộng ≤ 0) thì bỏ và đếm: lõi bản đồ không lập chỉ mục được nhưng stSegClear vẫn thấy, nên không được lọt vào. */
import { CONFIG } from '../../config';
import { collectBuildings, type Rect } from '../../environment/riverfront/clearance';
import { getRiverfront } from '../../environment/riverfront';
import { stAddSolids, type StMap, type StSolid } from './map';

export const stSceneStats = { buildings: 0, footprints: 0, skipped: 0 };

const stGood = (r: Rect): boolean => Number.isFinite(r.x0) && Number.isFinite(r.x1) && Number.isFinite(r.z0) && Number.isFinite(r.z1) && r.x1 > r.x0 && r.z1 > r.z0;

export function stCollectRuntime(map: StMap): number {
  const B = CONFIG.stroll.bounds, out: StSolid[] = [];
  let nb = 0, nf = 0, bad = 0;
  for (const b of collectBuildings()) {
    const r = { x0: b.x - b.w / 2, x1: b.x + b.w / 2, z0: b.z - b.d / 2, z1: b.z + b.d / 2 };
    if (!stGood(r)) { bad++; continue; }
    if (r.x1 < B.x0 || r.x0 > B.x1 || r.z1 < B.z0 || r.z0 > B.z1) continue;
    out.push({ kind: 'rect', ...r }); nb++;
  }
  const love = map.zones.find((z) => z.id === 'love');
  for (const f of getRiverfront()?.footprints ?? []) {
    if (!stGood(f)) { bad++; continue; }
    const cx = (f.x0 + f.x1) / 2, cz = (f.z0 + f.z1) / 2;
    if (love && cx >= love.x0 && cx <= love.x1 && cz >= love.z0 && cz <= love.z1) continue;
    out.push({ kind: 'rect', x0: f.x0, x1: f.x1, z0: f.z0, z1: f.z1 }); nf++;
  }
  if (bad) console.warn(`[stroll] bỏ ${bad} vật cản hỏng khi thu từ cảnh`);
  stSceneStats.buildings = nb; stSceneStats.footprints = nf; stSceneStats.skipped = bad;
  stAddSolids(map, out);
  return out.length;
}
/* ============================ Đi dạo: chuyển động nhân vật (thuần) ============================
   Mỗi khung: đọc đầu vào, đổi tốc độ / hướng mặt, nhảy, đi qua stMove (va chạm), bám cao độ đứng, chọn dáng (pose).
   Thuần: không import three, không đụng DOM. stStep chạy mỗi khung nên không cấp phát (D-018): dùng đối tượng tạm cấp module.
   - dt kẹp về dtMax: khung rất dài (tab ẩn rồi quay lại) không làm nhân vật vọt qua tường, chỉ chậm đi một khung.
   - Hướng: tới = (cos yaw, 0, −sin yaw), yaw tăng là quay trái (như flight.ts).
   - Cổng nhịp quay đóng dưới chân (vị trí không còn hợp lệ): stMove đóng băng khi điểm xuất phát không hợp lệ, nên sơ tán KHÔNG dùng stMove:
     tính một lần điểm hợp lệ gần nhất (stNearestValid, đắt), rồi đi thẳng tới đó với tốc độ chạy, bỏ qua đầu vào; tới nơi thì trả điều khiển. */
import { CONFIG } from '../../config';
import { stMove, stValid, stGroundY, stNearestValid, type StMap } from './map';
import { stSpawn } from './mapData';

export const ST_POSE_IDLE = 0, ST_POSE_WALK = 1, ST_POSE_RUN = 2, ST_POSE_JUMP = 3, ST_POSE_PHOTO = 4;

export interface StState {
  x: number; y: number; z: number;   // y: cao độ chân tuyệt đối, m
  yaw: number; speed: number;        // speed: tốc độ mặt bằng, m/s
  vy: number; air: boolean;          // vy: vận tốc đứng, m/s
  pose: number; evac: boolean;
  photo: number;                     // giây còn giơ tay chụp
  tx: number; tz: number;            // điểm sơ tán đã tính (chỉ có nghĩa khi evac)
}
export interface StInput { mx: number; mz: number; run: boolean; jump: boolean; camYaw: number }

const EPS_STEP = 1e-3;      // dung sai khi so bậc cao độ với stepMax (bậc Cầu Rồng lề ↔ bờ đo 0,3500083), m
const V_STOP = 0.1;         // m/s — dưới mức này coi là đứng yên
const _mv = { x: 0, z: 0 };      // kết quả stMove
const _near = { x: 0, z: 0 };    // kết quả stNearestValid

export function stCreate(map: StMap, slot: number): StState {
  const p = { x: 0, z: 0 };
  stSpawn(map, slot, p);
  const g = stGroundY(map, p.x, p.z);
  return { x: p.x, y: g === g ? g : CONFIG.roadY, z: p.z, yaw: CONFIG.stroll.spawnYaw, speed: 0, vy: 0, air: false, pose: ST_POSE_IDLE, evac: false, photo: 0, tx: p.x, tz: p.z };
}

export function stPhotoPose(s: StState): void { s.photo = CONFIG.stroll.photoHold; }

/* quay yaw về đích theo đường ngắn nhất, tốc độ mũ turn (1/s) */
function stTurn(yaw: number, target: number, turn: number, dt: number): number {
  let d = (target - yaw) % (2 * Math.PI);
  if (d > Math.PI) d -= 2 * Math.PI; else if (d < -Math.PI) d += 2 * Math.PI;
  const k = turn * dt;
  return yaw + d * (k < 1 ? k : 1);
}

/* Sơ tán: đi thẳng tới (tx, tz) với tốc độ chạy, mỗi khung không quá run × dt */
function stEvacStep(s: StState, map: StMap, dt: number): void {
  const C = CONFIG.stroll, dx = s.tx - s.x, dz = s.tz - s.z, dist = Math.sqrt(dx * dx + dz * dz), step = C.run * dt;
  s.photo = 0; s.speed = C.run; s.pose = ST_POSE_RUN;
  if (dist > 1e-9) s.yaw = stTurn(s.yaw, Math.atan2(-dz, dx), C.turn, dt);
  if (dist <= step) { s.x = s.tx; s.z = s.tz; s.evac = false; s.speed = 0; s.pose = ST_POSE_IDLE; }
  else { s.x += dx / dist * step; s.z += dz / dist * step; }
  const g = stGroundY(map, s.x, s.z);
  if (g === g) s.y = g;                                  // ngoài mọi vùng (cổng đóng): giữ cao độ cũ
  s.air = false; s.vy = 0;
}

export function stStep(s: StState, inp: StInput, map: StMap, dt: number): void {
  const C = CONFIG.stroll;
  if (!(dt > 0)) return;
  if (dt > C.dtMax) dt = C.dtMax;

  /* 1) vị trí không còn hợp lệ với tường cao / vùng (tường thấp không tính: đáp xuống giữa tường thấp là chuyện của stMove) */
  if (!s.evac && !stValid(map, s.x, s.z, Infinity)) {
    s.evac = true;
    if (!stNearestValid(map, s.x, s.z, _near)) stSpawn(map, -1, _near);
    s.tx = _near.x; s.tz = _near.z;
  }
  if (s.evac) { stEvacStep(s, map, dt); return; }

  /* 2) hướng đi và tốc độ đích */
  const sc = Math.sin(inp.camYaw), cc = Math.cos(inp.camYaw);
  const dx = inp.mz * cc + inp.mx * sc, dz = -inp.mz * sc + inp.mx * cc;
  let len = Math.sqrt(dx * dx + dz * dz);
  const moving = len > 1e-6;
  if (len > 1) len = 1;
  const target = moving ? (inp.run ? C.run : C.walk) * len : 0;
  const da = C.accel * dt;
  if (s.speed < target) s.speed = s.speed + da < target ? s.speed + da : target;
  else s.speed = s.speed - da > target ? s.speed - da : target;
  let hx: number, hz: number;                            // hướng di chuyển: theo đầu vào; thả tay thì trượt theo hướng mặt đang hãm
  if (moving) { hx = dx / Math.sqrt(dx * dx + dz * dz); hz = dz / Math.sqrt(dx * dx + dz * dz); s.yaw = stTurn(s.yaw, Math.atan2(-hz, hx), C.turn, dt); }
  else { hx = Math.cos(s.yaw); hz = -Math.sin(s.yaw); }

  /* 3) nhảy: chỉ khi chạm đất */
  if (!s.air && inp.jump) { s.vy = Math.sqrt(2 * C.gravity * C.jumpHeight); s.air = true; }

  /* 4) đi (feet: độ cao chân trên cao độ đứng chỗ đang đứng) */
  const g0 = stGroundY(map, s.x, s.z);
  const feet = s.air && g0 === g0 ? Math.max(0, s.y - g0) : 0;
  const dist = s.speed * dt;
  stMove(map, s.x, s.z, hx * dist, hz * dist, feet, _mv);
  s.x = _mv.x; s.z = _mv.z;

  /* 5) cao độ */
  const g = stGroundY(map, s.x, s.z);
  if (s.air) {
    const ny = s.y + s.vy * dt - 0.5 * C.gravity * dt * dt;
    s.vy -= C.gravity * dt;
    if (g === g && ny <= g) {                            // chạm đất
      s.y = g; s.vy = 0; s.air = false;
      if (!stValid(map, s.x, s.z, 0) && stNearestValid(map, s.x, s.z, _near)) { s.x = _near.x; s.z = _near.z; const g2 = stGroundY(map, s.x, s.z); if (g2 === g2) s.y = g2; }   // đáp giữa tường thấp: đẩy ra mép gần nhất
    } else s.y = ny;
  } else if (g === g) {
    if (s.y - g > C.stepMax + EPS_STEP) { s.air = true; s.vy = 0; }   // bước xuống quá bậc: rơi
    else s.y = g;
  }

  /* 6) dáng */
  if (s.photo > 0) { if (moving || s.air) s.photo = 0; else { s.photo -= dt; if (s.photo < 0) s.photo = 0; } }
  const still = s.speed < V_STOP && !moving;
  if (s.air) s.pose = ST_POSE_JUMP;
  else if (s.photo > 0 && still) s.pose = ST_POSE_PHOTO;
  else if (s.speed < V_STOP) s.pose = ST_POSE_IDLE;
  else s.pose = s.speed > (C.walk + C.run) * 0.5 ? ST_POSE_RUN : ST_POSE_WALK;
}
/* ============================ Đi dạo: camera sau lưng ============================
   Camera quay quanh tâm xoay ở độ cao `cam.height` trên chân nhân vật, lùi `dist` theo yaw / pitch người chơi chọn (không tự quay theo nhân vật),
   nhìn vào điểm `cam.look` trên chân. Tâm xoay trễ `lag` giây theo nhân vật cho chuyển động mềm.
   Tránh vật cản bằng bản đồ 2D (spec §3 mục 4): đoạn mặt bằng từ TÂM NHÂN VẬT (vị trí thật, luôn hợp lệ) tới chỗ camera muốn đứng cắt bởi stSegClear
   (tường cao vô hạn + mép vùng đi được), lùi thêm `gap`. Tường là cao vô hạn nên camera bị kéo lại gần thì nâng lên cho khoảng cách 3D tới tâm xoay
   vẫn ≥ minDist (= max(minDist, dist × phần đi được) của plan, tính theo 3D): camera không bao giờ ra ngoài đoạn đã kiểm, nên không chui vào nhà.
   Khoảng mặt bằng cho phép co lại ngay, nở ra theo `lag` (không giật khi vừa thoát góc tường).
   Cuối cùng kẹp độ cao: ≥ cao độ đứng tại chỗ camera + 0,3 m, ngoài vùng thì ≥ landY. Không cấp phát (D-018). */
import * as THREE from 'three';
import { CONFIG } from '../../config';
import { stSegClear, stGroundY, type StMap } from './map';

export interface StCam { yaw: number; pitch: number }

const ST_CAM_FLOOR = 0.3;   // m — camera cao hơn cao độ đứng tại chỗ nó ít nhất chừng này (plan Task 6)
const piv = { x: 0, y: 0, z: 0, ok: false };   // tâm xoay đã trễ
let reach = Infinity;                           // khoảng mặt bằng camera đang được phép lùi, m

export function stCamPlace(camera: THREE.PerspectiveCamera, target: THREE.Vector3, s: { x: number; y: number; z: number }, c: StCam, map: StMap, dt: number, snap?: boolean): void {
  const K = CONFIG.stroll.cam;
  /* 1) tâm xoay trễ theo nhân vật */
  const hy = s.y + K.height;
  if (snap || !piv.ok) { piv.x = s.x; piv.y = hy; piv.z = s.z; piv.ok = true; }
  else if (dt > 0) { const k = 1 - Math.exp(-dt / K.lag); piv.x += (s.x - piv.x) * k; piv.y += (hy - piv.y) * k; piv.z += (s.z - piv.z) * k; }
  /* 2) chỗ camera muốn đứng: lùi dist theo yaw / pitch */
  const cp = Math.cos(c.pitch), sp = Math.sin(c.pitch), fx = Math.cos(c.yaw), fz = -Math.sin(c.yaw);
  const bx = piv.x - fx * K.dist * cp, bz = piv.z - fz * K.dist * cp;
  let cy = piv.y + K.dist * sp;
  /* 3) cắt theo bản đồ từ tâm nhân vật */
  let dx = bx - s.x, dz = bz - s.z;
  const L = Math.sqrt(dx * dx + dz * dz);
  if (L > 1e-6) { dx /= L; dz /= L; } else { dx = -fx; dz = -fz; }
  const t = L > 1e-6 ? stSegClear(map, s.x, s.z, bx, bz) : 1;
  let allow = t >= 1 ? L : L * t - K.gap;
  if (allow < 0) allow = 0;
  if (snap || allow < reach || !(dt > 0)) reach = allow;
  else reach += (allow - reach) * (1 - Math.exp(-dt / K.lag));
  const h = reach < L ? reach : L;
  const cx = s.x + dx * h, cz = s.z + dz * h;
  /* 4) khoảng cách 3D tới tâm xoay thật ≥ minDist: thiếu thì nâng camera (không lùi thêm vào tường) */
  const up = cy - hy;
  if (h * h + up * up < K.minDist * K.minDist) { const need = Math.sqrt(K.minDist * K.minDist - h * h); if (up < need) cy = hy + need; }
  /* 5) không thấp hơn mặt đứng tại chỗ camera / mặt đất */
  const g = stGroundY(map, cx, cz);
  const floor = g === g ? g + ST_CAM_FLOOR : CONFIG.landY;
  if (cy < floor) cy = floor;
  camera.position.set(cx, cy, cz);
  target.set(piv.x, piv.y - K.height + K.look, piv.z);
  camera.lookAt(target);
}

/* Kéo chuột / vuốt: sang phải quay camera sang phải (yaw giảm), kéo xuống nâng camera nhìn xuống (pitch tăng) */
export function stCamDrag(c: StCam, dxPx: number, dyPx: number, sens: number): void {
  const K = CONFIG.stroll.cam;
  c.yaw -= dxPx * sens;
  c.pitch += dyPx * sens;
  if (c.pitch < K.pitchMin) c.pitch = K.pitchMin; else if (c.pitch > K.pitchMax) c.pitch = K.pitchMax;
}
/* ============================ Đi dạo: đầu vào từ bàn phím (thuần) ============================
   W/↑ tới, S/↓ lùi, A/← trái, D/→ phải theo hướng camera; chéo chuẩn hóa về độ dài 1; Shift chạy; Space nhảy.
   Nhảy ở đây chỉ phản ánh phím đang giữ: index.ts biến nó thành một lần nhảy mỗi lần bấm (stStep nhảy mỗi khung jump = true khi chạm đất).
   Không cấp phát (gọi mỗi khung). */
import type { StInput } from './motion';

export function stInputFromKeys(keys: Set<string>, camYaw: number, out: StInput): StInput {
  let f = 0, r = 0;
  if (keys.has('w') || keys.has('arrowup')) f += 1;
  if (keys.has('s') || keys.has('arrowdown')) f -= 1;
  if (keys.has('d') || keys.has('arrowright')) r += 1;
  if (keys.has('a') || keys.has('arrowleft')) r -= 1;
  const len = Math.sqrt(f * f + r * r);
  if (len > 1) { f /= len; r /= len; }
  out.mz = f; out.mx = r; out.run = keys.has('shift'); out.jump = keys.has(' '); out.camYaw = camYaw;
  return out;
}
/* ============================ Đi dạo: chụp ảnh khung hình thành PNG ============================
   Ảnh là đúng khung WebGL vừa vẽ: stPhotoAfterRender chạy ngay sau lệnh vẽ chính trong animate (cùng tác vụ) nên toBlob đọc được bộ đệm vừa vẽ,
   không cần preserveDrawingBuffer. Nhãn tên và mọi phần tử HTML (kể cả chớp trắng) không có trong ảnh.
   Bấm nhiều lần trước khi khung kế tiếp vẽ chỉ xếp một yêu cầu. Kích thước ảnh lấy tại lúc chụp (canvas.width / height), không đọc lại sau.
   Điện thoại (hover: none) có canShare thì mở bảng chia sẻ; còn lại tải file qua <a download>. Hủy bảng chia sẻ (AbortError) không phải lỗi.
   Khi không có yêu cầu chờ, mỗi khung chỉ một phép so sánh, không cấp phát. */
import { CONFIG } from '../../config';
import { t } from '../../i18n';

let pending = false;   // có một yêu cầu chụp chờ khung kế tiếp
export let stPhotoLast: { name: string; size: number; w: number; h: number } | null = null;   // ảnh vừa chụp (cho test)

const pad = (n: number): string => (n < 10 ? '0' : '') + n;

/* danang-YYYYMMDD-HHMMSS.png theo giờ máy người dùng */
export function stPhotoName(d: Date): string {
  return `danang-${d.getFullYear()}${pad(d.getMonth() + 1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}.png`;
}

/* Thông báo ngắn ở ô riêng #stToast (không dùng chung #exMpNotice); một bộ hẹn giờ duy nhất, mỗi thông báo mới hủy bộ cũ */
let toastTimer = 0;
function notice(key: string): void {
  const el = document.getElementById('stToast');
  if (!el) return;
  el.textContent = t(key); el.hidden = false;
  window.clearTimeout(toastTimer);
  toastTimer = window.setTimeout(() => { el.hidden = true; el.textContent = ''; }, CONFIG.explore.multi.noticeMs);
}

export function stPhotoRequest(): void { pending = true; }

/* Tải file về qua <a download> */
function download(blob: Blob, name: string): void {
  const url = URL.createObjectURL(blob), a = document.createElement('a');
  a.href = url; a.download = name; a.style.display = 'none';
  document.body.appendChild(a); a.click(); a.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), CONFIG.stroll.photoUrlMs);
  notice('stPhotoSaved');
}

/* Lưu: chia sẻ trên điện thoại (lỗi khác AbortError như NotAllowedError thì tải về), còn lại tải về */
function save(blob: Blob, name: string): void {
  const file = new File([blob], name, { type: 'image/png' });
  const nav = navigator as Navigator & { canShare?: (d: ShareData) => boolean };
  if (window.matchMedia('(hover: none)').matches && nav.canShare && nav.canShare({ files: [file] })) {
    navigator.share({ files: [file] }).then(() => notice('stPhotoSaved'), (e: unknown) => { if ((e as { name?: string }).name !== 'AbortError') download(blob, name); });
    return;
  }
  download(blob, name);
}

/* Gọi ngay sau lệnh vẽ khung chính: nếu có yêu cầu thì chụp canvas */
export function stPhotoAfterRender(canvas: HTMLCanvasElement): void {
  if (!pending) return;
  pending = false;
  const w = canvas.width, h = canvas.height, name = stPhotoName(new Date());
  try {
    canvas.toBlob((blob) => {
      if (!blob || blob.size === 0) { notice('stPhotoFail'); return; }
      stPhotoLast = { name, size: blob.size, w, h };
      save(blob, name);
    }, 'image/png');
  } catch { notice('stPhotoFail'); }
}

