  const ph = now * a[o + 3] + a[o];   // giữ pha liền khi đổi nhịp: φ(now) không nhảy
  a[o] = (((ph - now * _var.cadence) % TAU) + TAU) % TAU; a[o + 1] = _var.amp; a[o + 2] = _var.flags; a[o + 3] = _var.cadence;
  s.amp = _var.amp; s.cadence = _var.cadence; s.flags = _var.flags;
  aVar.needsUpdate = true;
}

function stHide(i: number): void {
  const s = slots[i];
  s.track.reset(); s.live = false;
  stPlace(i, 0);
}

function stRefreshVisible(): void {
  if (!mesh) return;
  let any = false;
  for (const s of slots) if (s.live) { any = true; break; }
  mesh.visible = any;
}

/* Tốc độ danh định theo dáng cho người khác (gói vị trí không có tốc độ) */
const stPoseSpeed = (pose: number) => (pose === ST_POSE_RUN ? C.run : pose === ST_POSE_WALK ? C.walk : 0);

export const stAvatars = {
  get mesh(): THREE.InstancedMesh | null { return mesh; },
  get self(): number { return me; },   // slot nhân vật của mình, -1 nếu không có (nhãn tên bỏ qua slot này)

  /* Dựng lần đầu gọi (lười, ngoài thứ tự dựng cảnh), các lần sau trả lại mesh cũ. Bên gọi thêm vào scene */
  build(): THREE.InstancedMesh {
    if (mesh) return mesh;
    const geo = ppBuildGeometry(), col = new THREE.Color();
    aVar = new THREE.InstancedBufferAttribute(new Float32Array(N * 4), 4); aVar.setUsage(THREE.DynamicDrawUsage);
    const pants = new Float32Array(N * 3);
    col.setHex(C.pants);
    for (let i = 0; i < N; i++) pants.set([col.r, col.g, col.b], i * 3);   // Color chuyển hex sRGB → tuyến tính
    geo.setAttribute('aVar', aVar);
    geo.setAttribute('aPants', new THREE.InstancedBufferAttribute(pants, 3));
    mesh = new THREE.InstancedMesh(geo, ppMaterial(), N);
    mesh.name = 'stroll-people';
    for (let i = 0; i < N; i++) { mesh.setColorAt(i, col.set(M.colors[i % M.colors.length])); mesh.setMatrixAt(i, _zero); }   // setColorAt bắt buộc (USE_INSTANCING_COLOR)
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    mesh.layers.set(1); mesh.castShadow = false; mesh.receiveShadow = false; mesh.frustumCulled = false;
    for (const s of slots) s.amp = s.cadence = s.flags = -1;
    for (let i = 0; i < N; i++) stPlace(i, 0);
    stRefreshVisible();
    return mesh;
  },

  /* Nhân vật của mình ở slot (đi một mình: 0); s = null thì bỏ hiện slot đó */
  setSelf(slot: number, s: StState | null): void {
    if (s === null) {
      if (me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); }
      me = -1; stRefreshVisible(); return;
    }
    const x = slots[slot];
    if (!x) return;
    if (me !== slot && me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); }
    me = slot; x.who = 1; x.track.reset();
    const t = x.st;
    t.x = s.x; t.y = s.y; t.z = s.z; t.yaw = s.yaw; t.pose = s.pose;
    x.live = true;
    stPlace(slot, s.speed);
    stRefreshVisible();
  },

  /* Danh sách người đi dạo đổi (sảnh, vào, ra): slot đổi chủ thì xóa mẫu, ẩn tới mẫu đầu; slot trống thì ẩn. Slot của mình do setSelf lo */
  sync(walkers: Flyer[], mySlot: number): void {
    if (mySlot !== me && me >= 0 && slots[me]?.who === 1) { slots[me].who = 0; stHide(me); me = -1; }   // đổi slot của mình: setSelf sẽ đặt lại
    for (let i = 0; i < N; i++) {
      const s = slots[i];
      let name: string | null = null;
      for (const w of walkers) if (w.slot === i) { name = w.name; break; }
      if (i === mySlot) { s.name = name; if (s.who === 2) { s.who = 0; stHide(i); } continue; }   // slot vừa thành của mình: bỏ người khác cũ, chờ setSelf
      if (name === null) { s.name = null; if (s.who === 2) { s.who = 0; stHide(i); } continue; }
      if (name !== s.name || s.who !== 2) { s.name = name; s.who = 2; stHide(i); }
    }
    stRefreshVisible();
  },

  /* Gói vị trí gộp: w = [slot, x, y, z, yaw, pose, giờ gửi?]; chỉ nhận slot người khác đã biết chủ */
  onPos(w: number[][], nowMs: number): void {
    for (const e of w) {
      const i = e[0], s = slots[i];
      if (!s || i === me || s.who !== 2) continue;
      s.track.feed(e, nowMs, M);
    }
  },

  /* Mỗi khung: đặt người khác theo mẫu nội suy (pose bậc thang) */
  update(nowMs: number): void {
    const t = nowMs - M.interpSends * 1000 / M.sendHz;
    for (let i = 0; i < N; i++) {
      const s = slots[i];
      if (s.who !== 2) continue;
      if (!s.track.sample(t, s.pose, true)) { if (s.live) { s.live = false; stPlace(i, 0); } continue; }
      const p = s.pose, st = s.st;
      st.x = p.x; st.y = p.y; st.z = p.z; st.yaw = p.yaw; st.pose = Math.round(p.bank);
      s.live = true;
      stPlace(i, stPoseSpeed(st.pose));
    }
    stRefreshVisible();
  },

  /* Trạng thái đang hiện của slot (cho nhãn tên, camera dù lượn); null nếu trống hoặc chưa có mẫu */
  slotState(slot: number): { x: number; y: number; z: number; yaw: number; pose: number } | null {
    const s = slots[slot];
    return s && s.live ? s.st : null;
  },

  /* Tên người ở slot (theo sync, cả slot của mình); null nếu trống hoặc đi một mình */
  name(slot: number): string | null { const s = slots[slot]; return s ? s.name : null; },

  /* Rời chế độ / rời phòng: ẩn hết, quên tên (mesh giữ lại để tái dùng) */
  clear(): void {
    me = -1;
    for (let i = 0; i < N; i++) { const s = slots[i]; s.who = 0; s.name = null; stHide(i); }
    stRefreshVisible();
  }
};
/* ============================ Đi dạo: điều khiển cảm ứng ============================
   Ba con trỏ độc lập trên #stHud: cần gạt #stPad (ngón trái), vuốt #stLook (nửa phải, dưới các nút), nút #stJump; #stPhoto là nút bấm thường (cả máy tính).
   - Mỗi vùng chỉ theo con trỏ đã chạm vào nó (pointerId riêng + setPointerCapture), nên giữ cần gạt, vuốt camera và chạm Nhảy cùng lúc không lẫn nhau.
   - Nhảy theo cạnh: một lần chạm gọi jump() một lần (stStep nhảy lại ngay khi chạm đất nếu jump còn giữ).
   - Thả tay, pointercancel, lostpointercapture, blur, ẩn tab, xoay màn hình, đổi cỡ khung nhìn: reset() — cần gạt về giữa, nhân vật dừng (Review Focus 2).
   - read(out) chỉ ghi đè mx / mz / run khi cần gạt đang được giữ (cảm ứng ưu tiên phím); mỗi khung không cấp phát (D-018). */
import { CONFIG } from '../../config';
import { stStick } from './stick';
import type { StInput } from './motion';

export interface StTouchHandlers { look(dxPx: number, dyPx: number): void; jump(): void; photo(): void; activity(): void }

export function stTouchBind(root: HTMLElement, h: StTouchHandlers): { read(out: StInput): void; reset(): void } {
  const pad = root.querySelector<HTMLElement>('#stPad'), knob = root.querySelector<HTMLElement>('#stKnob');
  const look = root.querySelector<HTMLElement>('#stLook'), jump = root.querySelector<HTMLElement>('#stJump'), photo = root.querySelector<HTMLElement>('#stPhoto');
  const size = CONFIG.stroll.stick.size;
  root.style.setProperty('--st-pad', size + 'px');   // đường kính cần gạt lấy từ CONFIG
  let padId = -1, cx = 0, cy = 0, dx = 0, dy = 0, r = size / 2;   // cần gạt: con trỏ, tâm (px màn hình, chốt lúc chạm), độ lệch núm
  let lookId = -1, lx = 0, ly = 0;                                 // vuốt camera: con trỏ, vị trí trước
  let jumpId = -1;
  const own = (el: HTMLElement, e: PointerEvent) => { try { el.setPointerCapture(e.pointerId); } catch { /* con trỏ không còn hoạt động (sự kiện giả) */ } };

  const knobTo = (x: number, y: number) => { if (knob) knob.style.transform = x === 0 && y === 0 ? '' : `translate(${x}px,${y}px)`; };
  const reset = () => { padId = -1; lookId = -1; jumpId = -1; dx = 0; dy = 0; knobTo(0, 0); };

  if (pad) {
    pad.addEventListener('pointerdown', (e) => {
      if (padId >= 0) return;
      e.preventDefault();
      const b = pad.getBoundingClientRect();
      cx = b.left + b.width / 2; cy = b.top + b.height / 2; r = b.width / 2 || size / 2;
      padId = e.pointerId; own(pad, e); h.activity();
      pad.dispatchEvent(new PointerEvent('pointermove', { pointerId: e.pointerId, clientX: e.clientX, clientY: e.clientY }));   // núm theo ngón ngay lúc chạm
    });
    pad.addEventListener('pointermove', (e) => {
      if (e.pointerId !== padId) return;
      dx = e.clientX - cx; dy = e.clientY - cy;
      const d = Math.sqrt(dx * dx + dy * dy);
      if (d > r) { dx = dx / d * r; dy = dy / d * r; }   // núm không ra khỏi vòng
      knobTo(dx, dy); h.activity();
    });
    const padEnd = (e: PointerEvent) => { if (e.pointerId === padId) { padId = -1; dx = 0; dy = 0; knobTo(0, 0); } };
    pad.addEventListener('pointerup', padEnd);
    pad.addEventListener('pointercancel', padEnd);
    pad.addEventListener('lostpointercapture', padEnd);
  }

  if (look) {
    look.addEventListener('pointerdown', (e) => {
      if (lookId >= 0) return;
      e.preventDefault();
      lookId = e.pointerId; lx = e.clientX; ly = e.clientY; own(look, e); h.activity();
    });
    look.addEventListener('pointermove', (e) => {
      if (e.pointerId !== lookId) return;
      h.look(e.clientX - lx, e.clientY - ly); h.activity();
      lx = e.clientX; ly = e.clientY;
    });
    const lookEnd = (e: PointerEvent) => { if (e.pointerId === lookId) lookId = -1; };
    look.addEventListener('pointerup', lookEnd);
    look.addEventListener('pointercancel', lookEnd);
    look.addEventListener('lostpointercapture', lookEnd);
  }

  if (jump) {
    jump.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      if (jumpId < 0) { jumpId = e.pointerId; own(jump, e); h.jump(); h.activity(); }   // một lần chạm một lần nhảy
    });
    const jumpEnd = (e: PointerEvent) => { if (e.pointerId === jumpId) jumpId = -1; };
    jump.addEventListener('pointerup', jumpEnd);
    jump.addEventListener('pointercancel', jumpEnd);
    jump.addEventListener('lostpointercapture', jumpEnd);
  }

  if (photo) photo.addEventListener('click', () => { h.activity(); h.photo(); });   // chuột và chạm đều ra click

  window.addEventListener('blur', reset);
  document.addEventListener('visibilitychange', () => { if (document.hidden) reset(); });
  window.addEventListener('orientationchange', reset);
  window.addEventListener('resize', reset);

  return {
    read(out: StInput): void { if (padId >= 0) stStick(dx, dy, r, out); },
    reset
  };
}
/* ============================ Đi dạo: cần gạt ảo (thuần) ============================
   Độ lệch núm so với tâm (px, phải +, xuống +) → hướng đi (mz: lên màn hình là tới, mx: phải) độ dài 1 và cờ chạy.
   Gạt nhẹ (k < run) là đi, gạt hết cỡ (k ≥ run) là chạy; k < dead là vùng chết. Không cấp phát (gọi mỗi khung). */
import { CONFIG } from '../../config';

export function stStick(dx: number, dy: number, radius: number, out: { mx: number; mz: number; run: boolean }): void {
  const S = CONFIG.stroll.stick;
  const h = Math.sqrt(dx * dx + dy * dy);
  const k = radius > 0 ? Math.min(1, h / radius) : 0;
  if (k < S.dead || h < 1e-9) { out.mx = 0; out.mz = 0; out.run = false; return; }
  out.mx = dx / h; out.mz = -dy / h; out.run = k >= S.run;
}

